INSERT INTO dsl_history_diag_c55f1cd45627.history_extrema_v1 SELECT 'stock-20060104-20260414-v1','306f333e28c82c9f2c634d8a1eb64eb49d3092937d8ca7d2742d96ecdcf21a95','a460a741b13b2cea6066c7a973c246463d68c6eb083c07a50650ed8403f3ab17','2026-04-14',a.* FROM (SELECT b.mktcode,b.tgtcode,MAX(CASE WHEN b.bizdate='2026-04-14' THEN b.closePrice END) AS close_current,MIN(b.closePrice) AS close_min,MAX(b.closePrice) AS close_max,MAX(CASE WHEN b.bizdate='2026-04-14' THEN b.highPrice END) AS high_current,MIN(b.highPrice) AS high_min,MAX(b.highPrice) AS high_max,MAX(CASE WHEN b.bizdate='2026-04-14' THEN b.lowPrice END) AS low_current,MIN(b.lowPrice) AS low_min,MAX(b.lowPrice) AS low_max FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate<='2026-04-14' GROUP BY b.mktcode,b.tgtcode HAVING MAX(CASE WHEN b.bizdate='2026-04-14' THEN 1 ELSE 0 END)=1) a;
